from pathlib import Path

path = Path('build_site.py')
s = path.read_text()
start = s.index('def forum():')
end = s.index('\ndef protection(', start)
replacement = """def forum():
    body = f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/youth/">Youth</a><span>/</span><span>Forum</span></div>{eyebrow('Youth forum · moderated')}<h1>Make room for good questions.</h1><p>A calm, account-required space for learning, youth ideas and community conversation. New topics and replies are reviewed by FIKER staff before they appear publicly.</p></div></section><section class="section"><div class="shell"><div class="forum-note"><strong>Keep this space safe.</strong><p>Do not share a child’s name, exact address, phone number, school identifier or anything that could put someone at risk. This forum is not an emergency service; use a trusted adult or verified local emergency support if someone is in immediate danger.</p></div><div class="forum-auth" data-forum-auth role="status"><div><strong>Checking your sign-in…</strong><p>Forum participation requires a verified Manus account.</p></div></div><div class="forum-shell"><section class="forum-panel" aria-label="Forum discussions"><div class="forum-toolbar"><input data-forum-search type="search" placeholder="Search discussions" aria-label="Search discussions"><select data-forum-category aria-label="Filter by category"><option value="">All categories</option></select><button class="button button-primary button-small" type="button" data-new-topic>New topic {arrow()}</button></div><div class="forum-status" data-forum-status role="status" aria-live="polite"></div><div class="forum-list" data-forum-list></div><p class="forum-empty" data-forum-empty hidden>No approved discussions match that search yet.</p><article class="forum-thread" data-forum-thread aria-live="polite"><div class="forum-thread-head"><div><button class="button button-small button-quiet" type="button" data-thread-back>← Back to discussions</button><h2 data-thread-title>Discussion</h2><p class="muted" data-thread-meta></p></div><div class="forum-actions"><button class="button button-small button-quiet" type="button" data-report-thread>Report</button></div></div><div data-thread-body></div><div class="forum-replies" data-thread-replies></div><form class="forum-form" data-reply-form><label for="reply-body">Add a thoughtful reply<textarea id="reply-body" name="body" required minlength="2" maxlength="5000" placeholder="Share an idea, question or useful perspective"></textarea></label><button class="button button-primary" type="submit">Submit reply {arrow()}</button><div class="forum-status" data-reply-status role="status" aria-live="polite"></div></form></article></section><aside class="forum-panel"><form class="forum-form" data-topic-form hidden><h2>Start a new topic</h2><p class="muted">Your topic will be reviewed by FIKER staff before it is visible to the public.</p><div class="field-row"><label for="topic-title">Title<input id="topic-title" name="title" required minlength="8" maxlength="180" placeholder="What would you like to discuss?"></label><label for="topic-category">Category<select id="topic-category" name="category" required><option value="">Choose a category</option></select></label></div><label for="topic-body">Your discussion<textarea id="topic-body" name="body" required minlength="20" maxlength="5000" placeholder="Keep it respectful, clear and free of identifying details"></textarea></label><div class="forum-actions"><button class="button button-primary" type="submit">Send for review {arrow()}</button><button class="button button-small button-quiet" type="button" data-topic-cancel>Cancel</button></div><div class="forum-status" data-topic-status role="status" aria-live="polite"></div></form><div class="login-required"><p class="eyebrow">Community standard</p><h2>Listen first.</h2><p>FIKER’s forum should make space for questions without shaming people. Add context, avoid personal information and assume good faith while keeping boundaries clear.</p><div class="mini-list"><a href="/protection/rights/">Know your rights {arrow()}</a><a href="/resources/">Find resources {arrow()}</a><a href="/contact/">Contact FIKER {arrow()}</a></div></div></aside></div></div></section><div class="report-dialog" data-report-dialog role="dialog" aria-modal="true" aria-labelledby="report-title"><div class="report-card"><button class="button button-small button-quiet" type="button" data-report-close>Close</button><h2 id="report-title">Report a concern</h2><p class="muted">Tell FIKER staff why this content needs review. Do not include emergency details here.</p><form class="report-form" data-report-form><label>Reason<select name="reason" data-report-reason required><option value="">Choose one</option><option>Safety concern</option><option>Personal information</option><option>Hate or harassment</option><option>Spam or misleading</option><option>Other</option></select></label><label>Additional context<textarea name="details" maxlength="1000" placeholder="A short explanation, without identifying details"></textarea></label><button class="button button-primary" type="submit">Send report {arrow()}</button><div class="forum-status" data-report-status role="status" aria-live="polite"></div></form></div></div>'''
    return page('Youth forum','A moderated forum for youth questions, learning and community discussion with account-required posting and staff review.','/youth/forum/',body,'Youth','<link rel="stylesheet" href="/styles/forum.css">','<script src="/scripts/forum.js" defer></script>')


def admin_forum():
    body = f'''<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><span>Forum moderation</span></div>{eyebrow('Staff workspace')}<h1>Review before it reaches the public.</h1><p>Moderation controls for FIKER staff. Every action is role-gated, recorded and separate from public forum reading.</p></div></section><section class="section"><div class="shell"><div class="forum-note"><strong>Staff access only.</strong><p>If you should moderate this space but see an access message, FIKER’s protected admin identity configuration needs to be completed. Never share admin credentials in forum posts.</p></div><div class="forum-status" data-admin-status role="status" aria-live="polite"></div><div class="forum-admin-grid"><div class="admin-stat"><strong data-admin-stat="pendingThreads">—</strong><span>Pending topics</span></div><div class="admin-stat"><strong data-admin-stat="pendingReplies">—</strong><span>Pending replies</span></div><div class="admin-stat"><strong data-admin-stat="openReports">—</strong><span>Open reports</span></div></div><div class="content-grid"><section><h2>Moderation queue</h2><div class="admin-list" data-admin-queue><p class="forum-empty">Loading moderation queue…</p></div></section><aside><h2>Reports</h2><div class="admin-list" data-admin-reports><p class="forum-empty">Loading reports…</p></div></aside></div></div></section>'''
    return page('Forum moderation','Role-gated FIKER staff workspace for reviewing forum topics, replies and reports.','/admin/forum/',body,'Youth','<link rel="stylesheet" href="/styles/forum.css">','<script src="/scripts/forum.js" defer></script>')
"""
s = s[:start] + replacement + s[end:]
s = s.replace("pages = {'/':home(),", "pages = {'/':home(),")
# The admin page is intentionally added after the public page map so it is not part of public navigation.
marker = "for p in programs: pages[f\"/work/{p['slug']}/\"] = program_detail(p['slug'])"
s = s.replace(marker, "pages['/admin/forum/'] = admin_forum()\n" + marker)
# Include a server-served admin page in the route manifest but do not add APIs.
path.write_text(s)
